export function shotAt(film,time){let start=0;for(let index=0;index<film.shots.length;index++){const shot=film.shots[index];if(time<start+shot.duration||index===film.shots.length-1)return{...shot,index,start,progress:Math.max(0,Math.min(1,(time-start)/shot.duration))};start+=shot.duration}}
